 p.innerHTML='<div class="wallet-heading"><div><h1>'+E(state.wallet.name)+'</h1><p>Your business, in focus.</p></div>'+'<div class="wallet-next">'+button('Message my team','data-wallet-route="services"')+button(icon('spark')+'Ask Fran AI','data-wallet-ask="Give me an overview of my business"',true)+'</div>'+'</div><div class="wallet-home-layout"><section class="wallet-overview"><div class="wallet-section-title"><h2>At a glance</h2><span>Balances and latest reported results</span></div><div class="wallet-metrics">'+metric('Available cash',money(cash),'Across connected deposit accounts','data-wallet-cash')+metric(last?last.label+' net income':'Net income',money(last?.net),prev&&last?.net!==null&&prev.net!==null?(last.net>=prev.net?'+':'−')+money(Math.abs(last.net-prev.net))+' vs '+prev.label:'Connect monthly books','data-wallet-finance="net"')+metric('Recorded debt',money(M.sum(debts.map(r=>r.data),'balance')),debts.length+' loan'+(debts.length===1?'':'s')+' · view terms','data-wallet-debt')+'</div><div class="wallet-section-title"><div><h2>How the business is moving</h2><p>Net income · '+(points.length?'latest six reported months':'monthly books needed')+'</p></div>'+button('Explore accounting '+icon(),'data-wallet-route="books"')+'</div>'+(points.length?chart(points.slice(-6),'net','Monthly net income'):'<p class="wallet-empty">Your monthly books will bring revenue and profit trends into this view.</p>')+'<div class="wallet-insight"><div class="wallet-insight-mark">'+icon('spark')+'</div><div><h3>'+(six!==null?money(Math.abs(six))+(six<0?' net loss':' net income')+' across these six months':last?last.label+' is your latest reported month':'Your next useful connection')+'</h3><p>'+(last&&prev&&last.net!==null&&prev.net!==null?'Net income '+(last.net>=prev.net?'increased':'decreased')+' by '+money(Math.abs(last.net-prev.net))+' from '+prev.label+'. Open the analysis to separate sales, cost of goods and operating expenses.':'Connect accounting reports to explain what your business earned and where it went.')+'</p>'+button('Understand the movement '+icon(),'data-wallet-finance="net"')+'</div></div><div class="wallet-section-title"><h2>Your CoverPanda team</h2><span>People for the follow-through</span></div><div class="wallet-team-list">'+[['books','Accounting','Monthly books & QuickBooks'],['payroll','Payroll','Reports & labor questions'],['insurance','Insurance','Coverage, quotes & certificates'],['entity','Formation','Entity records & deadlines']].map(([k,l,n])=>'<button data-wallet-service="'+k+'"><span class="wallet-team-symbol">'+icon(k==='insurance'?'shield':k==='payroll'?'people':k==='entity'?'file':'chart')+'</span><span><strong>'+l+'</strong><small>'+n+'</small></span>'+icon('chat')+'</button>').join('')+'</div></section><aside class="wallet-brief"><h2>On your radar</h2><p>Dates and decisions worth your attention.</p>'+(due.length?due.slice(0,3).map(taskRow).join(''):'<p>No open deadlines recorded.</p>')+button('All deadlines '+icon(),'data-wallet-route="entity"')+'<div class="wallet-coverage-note">'+icon('shield')+'<h3>'+policies.length+' policies on file</h3><p>See your limits, term dates and source policies in one place.</p>'+button('Review coverage '+icon(),'data-wallet-route="insurance"')+'</div><div class="wallet-evidence-note"><h3>Your records are working here</h3><p>'+docs().length+' documents · '+records('payroll').length+' payroll summaries · '+(state.books||[]).length+' books connection</p>'+button('Explore my records '+icon(),'data-wallet-route="documents"')+'</div></aside></div>';
