 box.innerHTML='<div class="wallet-heading"><div><h2>Your coverage, clearly.</h2><p>Policies, questions and your insurance team together.</p></div>'+button(icon('chat')+'Message CoverPanda Insurance','data-wallet-service="insurance"',true)+'</div><div class="wallet-insurance-summary"><div>'+icon('shield')+'<span><strong>'+policies.length+' policies on file</strong><small>Source policies available below</small></span></div><div><strong>'+money(annual)+'</strong><small>Combined annual premium · not an amount due</small></div><div>'+button('Request a certificate','data-wallet-service="insurance" data-note="I need a certificate of insurance. Please help me confirm the holder, address and requirements."')+button('Request a quote','data-wallet-service="insurance" data-note="Please review my existing policies and prepare renewal or additional coverage options."')+'</div></div><nav class="wallet-tabs" aria-label="Coverage views">'+[['policies','Policies'],['quotes','Quotes & requests'],['renewals','Renewal calendar']].map(([v,l])=>button(l,'data-wallet-ins-view="'+v+'" aria-pressed="'+(insuranceView===v)+'"')).join('')+'</nav>'+(insuranceView==='policies'?'<div class="wallet-policy-table"><div class="wallet-policy-labels"><span>Policy & carrier</span><span>Annual premium</span><span>Policy term</span><span>Status</span></div>'+policies.map((r,i)=>{const d=r.data,s=M.policyStatus(d);return '<details class="wallet-policy"><summary><span><strong>'+E(d.coverage_type)+'</strong><small>'+E(d.carrier)+' · '+E(d.policy_number)+'</small></span><span>'+money(d.annual_premium)+'</span><span>'+date(d.effective)+'<small>to '+date(d.expiration)+'</small></span>'+badge(s.label,s.tone)+'</summary><div class="wallet-policy-expanded"><div>'+coverageTable(d)+'<p class="wallet-note">Selected limits extracted from the policy. Terms, exclusions and endorsements remain in the original.</p></div><aside><h3>Keep this close</h3><p>'+E(d.location||state.wallet.name)+'</p>'+sourceButton(r)+button('Ask about this coverage','data-wallet-ask="What is my '+E(d.coverage_type)+' coverage?" data-context="insurance"')+'</aside></div></details>';}).join('')+'</div><div class="wallet-insight"><div class="wallet-insight-mark">'+icon('spark')+'</div><div><h3>Check a limit, then open the original.</h3>'+footer('insurance','When does my policy expire?')+'</div></div>'+(other.length?'<h3>Supporting records</h3><div class="wallet-document-links">'+other.map(sourceButton).join('')+'</div>':''):insuranceView==='renewals'?'<div class="wallet-renewals">'+policies.map(r=>'<article><time>'+date(r.data.expiration)+'</time><h3>'+E(r.data.coverage_type)+'</h3><p>'+E(r.data.carrier)+' · '+E(r.data.policy_number)+'</p>'+button('Plan this renewal','data-wallet-service="insurance" data-note="Please review the renewal of '+E(r.data.coverage_type)+' ending '+E(r.data.expiration)+'."')+'</article>').join('')+'</div><p class="wallet-note">These dates come from the stored policy terms. Renewal or cancellation outside the portal is not automatically synchronized.</p>':'<div class="wallet-empty"><h3>One conversation for your next coverage decision.</h3><p>'+ (requests.length?'Your insurance request is saved. Open the conversation to review updates and add requirements.':'No quotes have been added yet. Ask CoverPanda Insurance for a quote or a review of your existing coverage.')+'</p>'+button(requests.length?'Open insurance conversation':'Request coverage options','data-wallet-service="insurance"',true)+'</div>');
