function coverageRows(d){return [['General liability · each occurrence','general_liability_each_occurrence'],['General liability · aggregate','general_liability_aggregate'],['Umbrella · each occurrence','umbrella_each_occurrence'],['Business personal property','business_personal_property'],['Tenant improvements','tenant_betterments_improvements'],['Employers’ liability · each accident','employers_liability_each_accident'],['Property deductible','property_deductible']].filter(([,k])=>M.number(d[k])!==null).map(([l,k])=>[l,money(d[k])]);}
