 if(d.document_type==='insurance_policy')content=coverageTable(d)+'<dl class="wallet-facts"><dt>Carrier</dt><dd>'+E(d.carrier)+'</dd><dt>Policy number</dt><dd>'+E(d.policy_number)+'</dd><dt>Policy term</dt><dd>'+date(d.effective)+' – '+date(d.expiration)+'</dd><dt>Annual premium</dt><dd>'+money(d.annual_premium)+'</dd></dl><h3>Who to contact</h3><p>CoverPanda Insurance is your wallet support team. The carrier shown above remains the insurer on the policy.</p>'+button('Message insurance team','data-wallet-service="insurance"')+'<h3>For your company records</h3><p>Keep the full policy and endorsements with this location. Request a certificate for a landlord, franchisor or venue; a policy summary is not a certificate of insurance.</p>';
 if(d.document_type==='tax_return')content='<p>'+E(d.tax_year)+' · Form '+E(d.form)+' · '+E(d.entity)+'</p><div class="wallet-waterfall">'+[['Gross receipts',d.gross_receipts],['Cost of goods',d.cost_of_goods_sold],['Gross profit',d.gross_profit],['Ordinary business income',d.ordinary_business_income],['Salaries & wages',d.salaries_wages]].map(([l,v])=>'<div><span>'+l+'</span><strong>'+money(v)+'</strong></div>').join('')+'</div><p class="wallet-note">Annual tax-basis figures. These do not establish monthly net income or current ownership.</p>'+button('Ask accounting team','data-wallet-service="books"');
